Here is a Rust module from a small key-value cache crate:

```rust
use std::collections::HashMap;
use std::time::{Duration, Instant};

pub struct Entry<V> {
    value: V,
    inserted_at: Instant,
    ttl: Duration,
}

impl<V> Entry<V> {
    fn is_expired(&self) -> bool {
        self.inserted_at.elapsed() > self.ttl
    }
}

pub struct TtlCache<K, V> {
    map: HashMap<K, Entry<V>>,
    default_ttl: Duration,
}

impl<K: std::hash::Hash + Eq + Clone, V: Clone> TtlCache<K, V> {
    pub fn new(default_ttl: Duration) -> Self {
        Self {
            map: HashMap::new(),
            default_ttl,
        }
    }

    pub fn insert(&mut self, key: K, value: V) {
        self.map.insert(
            key,
            Entry {
                value,
                inserted_at: Instant::now(),
                ttl: self.default_ttl,
            },
        );
    }

    pub fn get(&self, key: &K) -> Option<V> {
        if let Some(entry) = self.map.get(key) {
            if entry.is_expired() {
                return None;
            }
            return Some(entry.value.clone());
        }
        None
    }

    pub fn len(&self) -> usize {
        self.map.len()
    }

    pub fn evict_expired(&mut self) {
        self.map.retain(|_, entry| !entry.is_expired());
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basic_insert_and_get() {
        let mut cache: TtlCache<String, i32> = TtlCache::new(Duration::from_secs(60));
        cache.insert("a".to_string(), 1);
        assert_eq!(cache.get(&"a".to_string()), Some(1));
    }

    #[test]
    fn expired_entry_returns_none() {
        let mut cache: TtlCache<String, i32> = TtlCache::new(Duration::from_millis(1));
        cache.insert("a".to_string(), 1);
        std::thread::sleep(Duration::from_millis(5));
        assert_eq!(cache.get(&"a".to_string()), None);
    }

    #[test]
    fn evict_expired_removes_stale_entries() {
        let mut cache: TtlCache<String, i32> = TtlCache::new(Duration::from_millis(1));
        cache.insert("a".to_string(), 1);
        cache.insert("b".to_string(), 2);
        std::thread::sleep(Duration::from_millis(5));
        cache.evict_expired();
        assert_eq!(cache.len(), 0);
    }
}
```

Bug report: `evict_expired` still leaves stale entries in the map under heavy concurrent read load in production, even though the unit tests above pass. We suspect `get()` is only a read-side filter and never actually removes the expired entry from the underlying map, so memory grows unbounded over time even when callers only ever call `get()` and never call `evict_expired()` on a schedule. Please: (1) explain precisely why the current code allows unbounded memory growth despite the passing tests, (2) modify `get()` so that it opportunistically removes an expired entry it encounters (self-healing lazy eviction), and (3) show the complete corrected `get()` method plus any other method signatures that must change as a result (for example, `&self` vs `&mut self`). Keep the public API names the same. Provide the full corrected code block for just the changed methods, not the whole file.
